<?php
namespace App\Http\Controllers;
use App\Http\Requests\AdoptionListingRequest; use App\Models\{AdoptionListing,AdoptionInterest,Shelter,ShelterCareLog}; use Illuminate\Http\Request;
class AdoptionController extends Controller { public function index(Request $r){return AdoptionListing::with('shelter')->where('status','available')->when($r->species,fn($q,$v)=>$q->where('species',$v))->when($r->breed,fn($q,$v)=>$q->where('breed','like','%'.$v.'%'))->paginate(20);} public function show(AdoptionListing $listing){return $listing->load('shelter','careLogs');} public function store(AdoptionListingRequest $r){$s=Shelter::where('user_id',$r->user()->id)->firstOrFail();return response()->json($s->adoptionListings()->create($r->validated()),201);} public function update(AdoptionListingRequest $r,AdoptionListing $listing){abort_unless($listing->shelter->user_id===$r->user()->id,403);$listing->update($r->validated());return $listing;} public function interest(Request $r,AdoptionListing $listing){$d=$r->validate(['message'=>'required|string|max:2000']);return AdoptionInterest::updateOrCreate(['adoption_listing_id'=>$listing->id,'user_id'=>$r->user()->id],['message'=>$d['message'],'status'=>'pending']);} public function updateInterest(Request $r,AdoptionInterest $interest){abort_unless($interest->user_id===$r->user()->id||$interest->listing->shelter->user_id===$r->user()->id,403);$interest->update($r->validate(['status'=>'required|in:pending,contacted,approved,rejected,adopted']));return $interest;} public function careLog(Request $r,AdoptionListing $listing){abort_unless($listing->shelter->user_id===$r->user()->id,403);$d=$r->validate(['logged_at'=>'required|date','category'=>'required|string|max:100','notes'=>'required|string']);return ShelterCareLog::create($d+['adoption_listing_id'=>$listing->id,'shelter_id'=>$listing->shelter_id,'created_by'=>$r->user()->id]);} }
